/* Legacy DOC form text is isolated separately from the stricter checklist-line reader. */
(function(root){'use strict';async function read(file){if(!file||file.size<512||file.size>2*1024*1024)throw Error('旧DOC须在2MiB以内');const bytes=new Uint8Array(await file.arrayBuffer());if(![208,207,17,224,161,177,26,225].every((v,i)=>bytes[i]===v))throw Error('不是Word97–2003二进制DOC');if(!root.LegacyDocFactory)throw Error('DOC组件未加载');const code='const reader=('+root.LegacyDocFactory.toString()+')();onmessage=e=>{try{const text=reader(new Uint8Array(e.data));if(typeof text!=="string"||text.length>150000||!text.trim())throw Error();postMessage({text});}catch(e){postMessage({error:true});}};';const url=URL.createObjectURL(new Blob([code],{type:'text/javascript'}));let worker;try{return await new Promise((ok,no)=>{let done=false,timer;const finish=(e,v)=>{if(done)return;done=true;clearTimeout(timer);worker?.terminate();e?no(e):ok(v);};worker=new Worker(url);worker.onmessage=e=>e.data.error?finish(Error('DOC正文无法完整读取，请另存DOCX后导入')):finish(null,e.data.text.replace(/[\u0000-\u0008\u000e-\u001f]/g,'').replace(/\r\n|[\r\v\f]/g,'\n'));worker.onerror=()=>finish(Error('DOC隔离读取失败'));timer=setTimeout(()=>finish(Error('DOC读取超时')),5000);worker.postMessage(bytes.buffer,[bytes.buffer]);});}finally{worker?.terminate();URL.revokeObjectURL(url);}}root.WorkpaperDocs=Object.freeze({read});})(globalThis);
